    function getLatestValue(value) {
        let strValue = String(value);
        if (strValue.includes('->')) {
            const parts = strValue.split('->');
            strValue = parts[parts.length - 1].trim();
        }
        return strValue.replace(/\s*\(.*\)$/, '').trim();
    }

    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            return current.length > 0 ? current[0] : defaultValue;
        }
        return current;
    }

    function updateProgressBar(barId, valueMainId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);

        if (!valueMainDisplay) return;

        const latestValue = getLatestValue(rawValueFromCharacterData);
        valueMainDisplay.innerText = latestValue;

        let numericValue = parseFloat(latestValue);
        if (isNaN(numericValue)) {
            const numericMatch = String(rawValueFromCharacterData).match(/(-?\d+(\.\d+)?)/);
            numericValue = numericMatch ? parseFloat(numericMatch[0]) : min;
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) progressBar.style.backgroundColor = color;
        }
    }

    function setTextContent(elementId, value) {
        const element = document.getElementById(elementId);
        if (element) {
            element.innerText = getLatestValue(value);
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.querySelector('.status-container').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据</p>";
                return;
            }
            const gameData = messages[0].data;
            let characterData;

            if (Object.keys(gameData).length === 2 && gameData.hasOwnProperty('凛') && gameData.hasOwnProperty('澪')) {
                characterData = gameData;
            } else if (gameData.display_data) {
                characterData = gameData.display_data;
            } else if (gameData.stat_data) {
