            if (characterData.hasOwnProperty('凛')) {
                const rinData = characterData['凛'];
                updateProgressBar('rin-trust-bar', 'rin-trust', SafeGetValue(rinData, '信任值', 0), 0, 100, 'var(--rin-primary)');
