                updateProgressBar('rin-lust-bar', 'rin-lust', SafeGetValue(rinData, '情欲值', 0), 0, 100, 'var(--rin-primary)');
                setTextContent('rin-boundary', SafeGetValue(rinData, '身体界线'));
                setTextContent('rin-thought', SafeGetValue(rinData, '心声'));
                setTextContent('rin-nipple-status', SafeGetValue(rinData, '身体状态.乳头'));
                setTextContent('rin-anus-status', SafeGetValue(rinData, '身体状态.肛门'));
                setTextContent('rin-pussy-status', SafeGetValue(rinData, '身体状态.小穴'));
                setTextContent('rin-womb-status', SafeGetValue(rinData, '身体状态.子宫'));
                setTextContent('rin-mouth-status', SafeGetValue(rinData, '身体状态.口腔'));
                setTextContent('rin-ear-status', SafeGetValue(rinData, '身体状态.耳朵'));
            }

            if (characterData.hasOwnProperty('澪')) {
                const mioData = characterData['澪'];
                updateProgressBar('mio-trust-bar', 'mio-trust', SafeGetValue(mioData, '信任值', 0), 0, 100, 'var(--mio-primary)');
                updateProgressBar('mio-enlightenment-bar', 'mio-enlightenment', SafeGetValue(mioData, '启蒙值', 0), 0, 100, 'var(--mio-primary)');
                updateProgressBar('mio-lust-bar', 'mio-lust', SafeGetValue(mioData, '情欲值', 0), 0, 100, 'var(--mio-primary)');
                setTextContent('mio-boundary', SafeGetValue(mioData, '身体界线'));
                setTextContent('mio-thought', SafeGetValue(mioData, '心声'));
                setTextContent('mio-nipple-status', SafeGetValue(mioData, '身体状态.乳头'));
                setTextContent('mio-anus-status', SafeGetValue(mioData, '身体状态.肛门'));
                setTextContent('mio-pussy-status', SafeGetValue(mioData, '身体状态.小穴'));
                setTextContent('mio-womb-status', SafeGetValue(mioData, '身体状态.子宫'));
                setTextContent('mio-mouth-status', SafeGetValue(mioData, '身体状态.口腔'));
                setTextContent('mio-ear-status', SafeGetValue(mioData, '身体状态.耳朵'));
            }

            const allSections = document.querySelectorAll('.section-header');
            allSections.forEach(header => {
                if (header.nextElementSibling.classList.contains('expanded')) {
                    header.nextElementSibling.classList.remove('expanded');
                    header.querySelector('span:last-child').innerText = '▼';
                }
            });

            const firstHeaders = Array.from(allSections).slice(0, 2);
            firstHeaders.forEach(header => toggleSection(header));

        } catch (error) {
            document.querySelector('.status-container').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
